valid_if:
=SORT(
 UNIQUE(
 LIST([_THISROW].[Shipment No])
 + SM_Today_User[Shipment No]
)
)

=IF(ISBLANK([Shipment No]),
LIST(),
 UNIQUE(
 IF(USERROLE() = "ADMIN",
SELECT(ตารางงานประจำวัน[Invoice No], [Shipment No] =[_THISROW].[Shipment No]),
 SELECT(SM_Today_User[InvoiceNo],
 AND(
 [Shipment No] = [_THISROW].[Shipment No],

NOT(IN([Invoice No], SCGนครหลวงJWDภูมิภาค[Invoice No]))
)
 )
 )
 + [_THISROW].[Invoice No]
 ) LIST("")
)

=IF(USERROLE() = "ADMIN",
(SM_Today_User[Shipment No] + 
 SELECT(ข้อมูลงานRT[Shipment (รับคืน)], [วันที่เข้ารับ] = TODAY())),
 IF([ข้อมูลการแจ้งปั ญหา] = "ไม่มีในจุดส่งงานวันนี้ ไม่สามารถเข้ารับงานคืนให้ได้",
 SELECT(ข้อมูลงานRT[Shipment (รับคืน)], 
 AND([Emailพนักงาน] = USEREMAIL(), [วันที่เข้ารับ] = TODAY())
 ),
SM_Today_User[Shipment No]
)
)

=UNIQUE(
 IF(USERROLE() ="ADMIN",
 SELECT(ตารางงานประจำวัน[Invoice No], [ShipmentNo] = [_THISROW].[Shipment No]) +
 SELECT(ข้อมูลงานRT[เลขที่เอกสารรับคืน], [Shipment (รับคืน)] = [_THISROW].[ShipmentNo]),
 IF([ข้อมูลการแจ้งปั ญหา] = "ไม่มีในจุดส่งงานวันนี้ ไม่สามารถเข้ารับงานคืนให้ได้",
 SELECT(ข้อมูลงานRT[เลขที่เอกสารรับคืน],
 AND(
 [Shipment (รับคืน)] = [_THISROW].[ShipmentNo],
 [Email พนักงาน] = USEREMAIL(),
 [วันที่เข้ารับ] =TODAY()
 )
 ),
 SELECT(SM_Today_User[Invoice No], 
AND(
 [Shipment No] = [_THISROW].[Shipment No],
[DeliveryStatus] <> "จัดส่งเรียบร้อย",
 NOT(IN([Invoice No],SELECT(แจ้งปั ญหาระหว่างวัน[Invoice No], [Shipment No] =[_THISROW].[Shipment No])))
 )
 )
 )
 ) 
 + [_THISROW].[Invoice No]
) LIST("")

=IF(
 ISBLANK([ShipmentNo]),
 LIST(),
 UNIQUE(
 SELECT(
 SM_Today_User2[Invoice No],
 AND(
 [Shipment No] = [_THISROW].[Shipment No],
 NOT(
 IN(
 [Invoice No],
 รับงานคืนได้เงิน200[Invoice No]
 )
 )
 )
 )
 + [_THISROW].[InvoiceNo]
 )
 LIST("")
)

=IF(USERROLE() = "ADMIN",
 SORT(
UNIQUE(
 LIST([_THIS]) + 
 SELECT(
SCGนครหลวงJWDภูมิภาค[Shipment No],
 AND(
 [วันที่ส่งสินค้า]>= EOMONTH(TODAY(), -2) + 1,
 NOT(IN([Shipment No], ทำเบิกส่วนต่างScgวังน้อย[Shipment No]))
 )
 )
 )
 ),
 SORT(
UNIQUE(
 LIST([_THIS]) + 
 SELECT(
SCGนครหลวงJWDภูมิภาค[Shipment No],
 AND(
 [Emailพนักงาน] = USEREMAIL(),
 [วันที่ส่งสินค้า] >= TODAY() - 1,
NOT(IN([Shipment No], ทำเบิกส่วนต่างScgวังน้อย[ShipmentNo]))
 )
 )
 )
)
)

=SELECT(
SCGนครหลวงJWDภูมิภาค[จุดส่งสินค้าปลายทาง], 
 AND(
[Shipment No] = [_THISROW].[Shipment No], 
 NOT(IN([จุดส่งสินค้าปลายทาง], SPLIT(TEXT(
 [_THISROW].[Lat/Long_ปลายทาง_01]
 ), " , "))
)
))

=SELECT(
SCGนครหลวงJWDภูมิภาค[จุดส่งสินค้าปลายทาง], 
 AND(
[Shipment No] = [_THISROW].[Shipment No], 
 NOT(IN([จุดส่งสินค้าปลายทาง], SPLIT(TEXT(
 [_THISROW].[Lat/Long_ปลายทาง_01] & " , " & 
 [_THISROW].[Lat/Long_ปลายทาง_02] 
 )," , "))
)
))

=AND(
 IN([_THIS],ตารางงานประจำวัน[Invoice No]),
 LOOKUP([_THIS], "ตารางงานประจำวัน", "Invoice No", "Plan Delivery") = [_THISROW].[เลือกวันที่],
 LOOKUP([_THIS], "ตารางงานประจำวัน", "Invoice No","จำนวน_Invoice_ที่ต้องสแกน") > 0,
 ISBLANK(
SELECT(ScanDocs[ID_ScanDocs], 
 OR([Scan_Invoice] =[_THIS], [Select_Invoice] = [_THIS])
 )
)
)

=AND(
 ISNOTBLANK([_THIS]),
 IN(
LOOKUP([_THIS], "ตารางงานประจำวัน", "ID_งานประจำวัน","Plan Delivery"),
 LIST(TODAY(), TODAY() - 1)
 ),
ISBLANK(
 SELECT(ScanDocs[ID_ScanDocs], 
 AND(
[Invoice_No] = [_THIS], 
 [ID_ScanDocs] <> [_THISROW].[ID_ScanDocs]
 )
 )
)
)

